import{_ as i,C as n,o,c as r,j as t,a as s,E as l,ag as d}from"./chunks/framework.DMVuHR7L.js";const y=JSON.parse('{"title":"Scripting","description":"","frontmatter":{},"headers":[],"relativePath":"features/scripting.md","filePath":"features/scripting.md","lastUpdated":1779647517000}'),h={name:"features/scripting.md"};function p(c,e,u,g,k,m){const a=n("ThemeImage");return o(),r("div",null,[e[0]||(e[0]=t("h1",{id:"scripting",tabindex:"-1"},[s("Scripting "),t("a",{class:"header-anchor",href:"#scripting","aria-label":'Permalink to "Scripting"'},"​")],-1)),e[1]||(e[1]=t("p",null,[s("The Scripting widget turns one shell script into a custom control panel. You write shell "),t("strong",null,"functions"),s("; you add "),t("strong",null,"controls"),s(` that run them or feed them values. It's a Tasker-style toolbox for the workflows you repeat — "Package toolbox", "Performance lab", an app-debugger panel — without building a real app.`)],-1)),l(a,{"src-dark":"/img/features/scripting-default.png","src-light":"/img/features/scripting-default-light.png",alt:"Scripting tile — a Package toolbox panel with a text input, action buttons, and a console"}),e[2]||(e[2]=d(`<h2 id="the-mental-model" tabindex="-1">The mental model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The mental model&quot;">​</a></h2><p>One panel owns one script. Every control&#39;s <strong>label</strong> decides the name the script sees — there&#39;s no second naming step:</p><ul><li>An <strong>input</strong> labelled <code>Package</code> exports its value as the env var <code>$PACKAGE</code>.</li><li>An <strong>action button</strong> labelled <code>Force stop</code> calls the function <code>force_stop</code> when pressed.</li><li>A bound <strong>display</strong> labelled <code>Battery temperature</code> calls <code>battery_temp</code> and shows its output.</li></ul><p>Names are derived deterministically — uppercased and snake-cased for variables, lowercased for functions (so <code>Force stop</code> → <code>$FORCE_STOP</code> as a value, <code>force_stop()</code> as a function). They use underscores, never hyphens, because the device shell (mksh) requires it.</p><p>Every input&#39;s current value is exported on <strong>every</strong> run, so any function can read any input. A <code>$PACKAGE</code> text field can drive a whole row of buttons:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">force_stop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> force-stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PACKAGE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clear_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PACKAGE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()       { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dumpsys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PACKAGE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> versionName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span></code></pre></div><h2 id="how-runs-work" tabindex="-1">How runs work <a class="header-anchor" href="#how-runs-work" aria-label="Permalink to &quot;How runs work&quot;">​</a></h2><p>Each run re-sources the whole script and calls one function, with input values supplied as environment variables. Values are passed as separate arguments, never spliced into the command text — so a value like <code>; rm -rf /</code> is inert data, not code. Output (stdout, stderr, exit code) lands in the panel&#39;s <strong>console</strong>.</p><p>Runs are one-shot — the script is re-sourced each time rather than kept in a long-lived shell, so a function is always defined by the current script and always sees the current input values.</p><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><p><strong>Inputs</strong> carry a value: text field, slider, knob, toggle, select, stepper. A toggle exports <code>1</code> / <code>0</code>; everything else exports its value verbatim.</p><p><strong>Action button</strong> runs a function. Mark it <em>Confirm before running</em> for destructive operations and it opens a Cancel / Run popover first.</p><p><strong>Displays</strong> show a bound function&#39;s output:</p><table tabindex="0"><thead><tr><th>Display</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Console</strong></td><td>The most recent run — stdout, stderr, and the exit code. On by default.</td></tr><tr><td><strong>Readout</strong></td><td>A big number + unit pulled from the output.</td></tr><tr><td><strong>Status pill</strong></td><td>A label + the output&#39;s last line, coloured by exit status.</td></tr><tr><td><strong>Gauge</strong></td><td>The output as a value on a min/max arc.</td></tr><tr><td><strong>LED</strong></td><td>A coloured indicator driven by the output (<code>green</code> / <code>amber</code> / <code>red</code> / <code>blue</code> / <code>off</code>, or truthiness).</td></tr></tbody></table><p>Displays refresh on a configurable <strong>auto-poll</strong> interval (off by default) and, optionally, whenever an input they read changes.</p><p><strong>Sections</strong> group controls under a heading. They&#39;re visual only — they don&#39;t change the shared environment.</p><h2 id="the-builder" tabindex="-1">The builder <a class="header-anchor" href="#the-builder" aria-label="Permalink to &quot;The builder&quot;">​</a></h2><p>The tile&#39;s cog opens the builder: the shell script on the left (with a <strong>Run as root</strong> toggle and a live legend of the variables and functions in scope), the controls list and per-control settings on the right. Drag to reorder controls; the split between panes is draggable and the controls pane can collapse to give the editor the full width. Changes are staged until you hit <strong>Save panel</strong>.</p><p>If the script fails a syntax check on a real device, the tile shows a <strong>script error</strong> banner — click it to jump back into the builder — and the action buttons are disabled until it parses.</p><h2 id="sharing-a-panel" tabindex="-1">Sharing a panel <a class="header-anchor" href="#sharing-a-panel" aria-label="Permalink to &quot;Sharing a panel&quot;">​</a></h2><p>Scripting panels travel with the dashboard&#39;s <a href="./dashboard#sharing">import / export</a>. Because an imported panel runs shell commands on your device, the importer must acknowledge that explicitly, and auto-polling displays start <strong>paused</strong> after an import — nothing runs until you choose to enable it.</p><h2 id="trying-it-without-a-device" tabindex="-1">Trying it without a device <a class="header-anchor" href="#trying-it-without-a-device" aria-label="Permalink to &quot;Trying it without a device&quot;">​</a></h2><p>On the <a href="./simulator">simulated stream</a>, the widget evaluates a small subset of shell — <code>echo</code> / <code>printf</code> with <code>$VAR</code> substitution — so a demo panel produces real-looking output with no phone attached.</p>`,23))])}const f=i(h,[["render",p]]);export{y as __pageData,f as default};
